using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ByteBitReverse;

public class BitReverser
{
    // Nibble-reverse lookup: index i maps to the bit-reversal of the 4-bit value i.
    private static ReadOnlySpan<byte> NibbleLut =>
        [0x0, 0x8, 0x4, 0xC, 0x2, 0xA, 0x6, 0xE,
         0x1, 0x9, 0x5, 0xD, 0x3, 0xB, 0x7, 0xF];

    // 256-byte scalar lookup table, built once.
    private static readonly byte[] ScalarLut = BuildScalarLut();

    private static byte[] BuildScalarLut()
    {
        var lut = new byte[256];
        ReadOnlySpan<byte> nib = NibbleLut;
        for (int i = 0; i < 256; i++)
            lut[i] = (byte)((nib[i & 0xF] << 4) | nib[i >> 4]);
        return lut;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int offset = 0;
        int length = data.Length;

        // --- Vector256 path (AVX2 / 32 bytes at a time) ---
        if (Vector256.IsHardwareAccelerated && length >= Vector256<byte>.Count)
        {
            var lut = Vector256.Create(NibbleLut, NibbleLut);
            var lowNibbleMask = Vector256.Create((byte)0x0F);

            int lastBlockStart = length - Vector256<byte>.Count;
            while (offset <= lastBlockStart)
            {
                var vec = Vector256.LoadUnsafe(ref ptr, (nuint)offset);
                var lo = vec & lowNibbleMask;
                var hi = Vector256.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & lowNibbleMask;
                var reversedLo = Vector256.Shuffle(lut, lo);
                var reversedHi = Vector256.Shuffle(lut, hi);
                var result = Vector256.ShiftLeft(reversedLo.AsInt16(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)offset);
                offset += Vector256<byte>.Count;
            }
        }
        // --- Vector128 path (SSE2/NEON / 16 bytes at a time) ---
        else if (Vector128.IsHardwareAccelerated && length >= Vector128<byte>.Count)
        {
            var lut = Vector128.Create(NibbleLut);
            var lowNibbleMask = Vector128.Create((byte)0x0F);

            int lastBlockStart = length - Vector128<byte>.Count;
            while (offset <= lastBlockStart)
            {
                var vec = Vector128.LoadUnsafe(ref ptr, (nuint)offset);
                var lo = vec & lowNibbleMask;
                var hi = Vector128.ShiftRightLogical(vec.AsInt16(), 4).AsByte() & lowNibbleMask;
                var reversedLo = Vector128.Shuffle(lut, lo);
                var reversedHi = Vector128.Shuffle(lut, hi);
                var result = Vector128.ShiftLeft(reversedLo.AsInt16(), 4).AsByte() | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)offset);
                offset += Vector128<byte>.Count;
            }
        }

        // --- Scalar tail via 256-byte LUT ---
        byte[] scalarLut = ScalarLut;
        while (offset < length)
        {
            Unsafe.Add(ref ptr, offset) = scalarLut[Unsafe.Add(ref ptr, offset)];
            offset++;
        }
    }
}

